#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Projectiles;
using MVZ2.GameContent.Shells;
using MVZ2.Vanilla.Armors;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using MVZ2Logic.Modding;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Tools;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class EjectorGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(VanillaLevelCallbacks.POST_EJECTED_ENTITY_LAND, PostEjectedEntityLandCallback);
            mod.AddTrigger(VanillaLevelCallbacks.POST_COMMAND_BLOCK_TRANSFORM, PostCommandBlockTransformCallback);
        }
        private void PostEjectedEntityLandCallback(VanillaLevelCallbacks.PostEjectedEntityLandParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            var damageMultiplier = param.damageMultiplier;
            var shell = entity.GetShellID();
            if (shell == VanillaShellID.cloud)
            {
                // 云落地时触发弹性云大招
                ElasticCloudEvocationBuff.Explode(entity, 120f);
            }
            else if (shell == VanillaShellID.lightning)
            {
                // 闪电落地时对半径2.5格内的敌人造成200伤害
                LightningLand(entity, damageMultiplier);
            }
            else if (shell == VanillaShellID.netherrack)
            {
                // 下界岩落地时爆出火焰
                NetherrackLand(entity, damageMultiplier);
            }
            else if (shell == VanillaShellID.ice)
            {
                // 冰落地时爆出冰锥
                IceLand(entity, damageMultiplier);
            }

            if (!entity.IsAIFrozen())
            {
                // 炸药落地后如果死亡，就引爆
                if (entity.TryBehaviourExplode(entity.GetRange(), entity.GetDamage()))
                {
                    entity.Remove();
                }
            }
        }
        private void PostCommandBlockTransformCallback(VanillaLevelCallbacks.PostCommandBlockTransformParams args, CallbackResultVoid result)
        {
            var commandBlock = args.commandBlock;
            var transformed = args.transformed;
            if (transformed == null || commandBlock == null)
                return;
            if (commandBlock.HasBuff<ThrownByEjectorBuff>())
            {
                transformed.AddBuff<ThrownByEjectorBuff>();
            }
        }
        private void LightningLand(Entity entity, float damageMultiplier)
        {
            thunderBuffer.Clear();
            thunderDetector.DetectMultiple(entity, thunderBuffer);
            var damage = 200 * damageMultiplier;
            for (int i = 0; i < thunderBuffer.Count; i++)
            {
                var collider = thunderBuffer[i];
                collider.TakeDamage(damage, new DamageEffectList(VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.LIGHTNING), entity);
            }
            var centerPos = entity.GetCenter();
            TNT.ExplodeArcs(entity, entity.GetCenter(), LIGHTNING_RADIUS);
            entity.PlaySound(VanillaSoundID.thunder);
            entity.PlaySound(VanillaSoundID.teslaAttack);
        }
        private void NetherrackLand(Entity entity, float damageMultiplier)
        {
            var level = entity.Level;
            // 留下火焰
            var column = entity.GetColumn();
            var lane = entity.GetLane();
            var param = entity.GetSpawnParams();
            param.SetProperty(VanillaEntityProps.DAMAGE, entity.GetDamage() * damageMultiplier * 0.01f);
            for (int x = column - 1; x <= column + 1; x++)
            {
                for (int y = lane - 1; y <= lane + 1; y++)
                {
                    var grid = level.GetGrid(x, y);
                    if (grid == null)
                        continue;
                    GridFire.Spawn(grid, entity, param);
                }
            }
            // 创建特效
            Explosion.Spawn(entity, entity.GetCenter(), 120)?.Let(e =>
            {
                e.SetTint(new Color(1, 0.2f, 0, 1));
            });
            level.ShakeScreen(10, 0, 15);
            entity.PlaySound(VanillaSoundID.explosion);
        }
        private void IceLand(Entity entity, float damageMultiplier)
        {
            if (!entity.IsDead)
                return;
            entity.PlaySound(VanillaSoundID.frozenOrb);
            var level = entity.Level;
            // 发射冰锥
            var count = 18;
            var angleInterval = 360f / count;
            for (int i = 0; i < count; i++)
            {
                var angle = angleInterval * i;
                var direction = Vector3.right.RotateClockwiseXZ(angle);
                var position = entity.GetCenter() + direction * (entity.GetScaledSize().x * 0.5f);
                var velocity = direction * 20;

                var boltDamage = 20 * damageMultiplier;

                var spawnParam = entity.GetSpawnParams();
                var projArgs = new ProjectileShootArgs(spawnParam);
                projArgs.damage = boltDamage;
                projArgs.position = position;
                projArgs.velocity = velocity;
                projArgs.projectileID = VanillaProjectileID.iceBolt;
                entity.ShootProjectile(projArgs);
            }

            var spawnParams = entity.GetSpawnParams();
            spawnParams.SetProperty(EngineEntityProps.TINT, new Color(0.75f, 0.85f, 1, 1));
            entity.Spawn(VanillaEffectID.smokeCluster, entity.GetCenter(), spawnParams);

            using var resultsItem = ListPool<IEntityCollider>.Rent();
            var results = resultsItem.Value;
            slowDetector.DetectMultiple(entity, results);
            foreach (var collider in results)
            {
                if (!collider.IsForMain())
                    continue;
                collider.Entity.InflictFrozenAndSlow(FROZEN_FRAMES, SLOW_FRAMES, new EntitySourceReference(entity));
            }
            entity.FreezeObjects(freezeObjectDetector);
        }
        public const float LIGHTNING_RADIUS = 200f;
        public const float SLOW_RADIUS = 120f;
        public const int FROZEN_FRAMES = 300;
        public const int SLOW_FRAMES = 300;
        private Detector thunderDetector = new SphereDetector(LIGHTNING_RADIUS)
        {
            canDetectInvisible = true
        };
        private Detector freezeObjectDetector = new SphereDetector(SLOW_RADIUS)
        {
            canDetectInvisible = true,
            mask = EntityCollisionHelper.MASK_ALL,
            factionTarget = FactionTarget.Any
        };
        private Detector slowDetector = new SphereDetector(SLOW_RADIUS)
        {
            canDetectInvisible = true,
            mask = EntityCollisionHelper.MASK_ENEMY,
        };
        private List<IEntityCollider> thunderBuffer = new List<IEntityCollider>(1024);
    }
}
